with enriched as (select e.*, p.dept_name, p.budget, p.location from employees e inner join departments p on e.dept_id = p.id) select date_trunc('week', hire_date) as week_start, sort_array(collect_set(dept_name)) as dept_name_list, count(*) filter (where job_title = 'Manager') as manager_rows, max(budget) as max_budget, round(sum(salary) / nullif(count(case when level = 'L5' then 1 end), 0), 2) as salary_per_l5, max(budget) filter (where dept_name = 'HR') as hr_max_budget from enriched group by week_start order by max_budget asc
